package com.smarthub.plus;
import android.content.Context;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.json.*;
/** On-demand public channel/logo indexes. No private server, embedded keys or bundled catalogue. */
final class ChannelCatalogue {
 private final Context context;private static final Map<String,JSONArray> memory=new HashMap<>();private static final Map<String,Long> fetched=new HashMap<>();
 ChannelCatalogue(Context c){context=c.getApplicationContext();}
 private JSONArray index(String name)throws Exception{synchronized(memory){long now=System.currentTimeMillis();if(memory.containsKey(name)&&now-fetched.get(name)<6*3600000L)return memory.get(name);File dir=new File(context.getCacheDir(),"channel-catalogue");dir.mkdirs();File cache=new File(dir,name+".json");String text="";long at=cache.lastModified();if(cache.isFile()&&now-at<6*3600000L)try(InputStream in=new FileInputStream(cache)){text=PlaylistRepository.readBounded(in);}else try{text=HubHttp.get("https://iptv-org.github.io/api/"+name+".json",8*1024*1024);try(FileOutputStream out=new FileOutputStream(cache)){out.write(text.getBytes(StandardCharsets.UTF_8));}at=now;}catch(Exception error){if(!cache.isFile())throw error;try(InputStream in=new FileInputStream(cache)){text=PlaylistRepository.readBounded(in);}context.getSharedPreferences("smarthub",0).edit().putString("satellite_logo_error","Online catalogue unavailable; using saved public index").apply();}JSONArray data=new JSONArray(text);memory.put(name,data);fetched.put(name,at);return data;}}
 JSONArray search(String raw)throws Exception{String q=normalized(raw);JSONArray out=new JSONArray(),rows=index("channels");if(q.length()<2)return out;for(int n=0;n<rows.length()&&out.length()<50;n++){JSONObject c=rows.optJSONObject(n);if(c==null)continue;boolean match=normalized(c.optString("name")).contains(q)||normalized(c.optString("id")).contains(q);JSONArray aliases=c.optJSONArray("alt_names");if(aliases!=null)for(int i=0;i<aliases.length();i++)if(normalized(aliases.optString(i)).contains(q))match=true;if(match)out.put(new JSONObject().put("id",c.optString("id")).put("name",c.optString("name")).put("country",c.optString("country")));}return out;}
 JSONObject logo(String name,String id)throws Exception{return match(name,id,index("channels"),index("logos"));}
 static String normalized(String value){return java.text.Normalizer.normalize((value==null?"":value).replaceAll("[إأآ]","ا"),java.text.Normalizer.Form.NFKC).toLowerCase(Locale.ROOT).replaceAll("[\\u064b-\\u065f\\u0640]","").replaceAll("[^\\p{L}\\p{N}]","");}
 private static String channel(String value){return normalized(value.replaceFirst("(?i)(?:\\s|\\(|\\[)+(?:SD|HD|FHD|UHD|4K)(?:\\)|\\])?\\s*$",""));}
 private static boolean alias(JSONObject c,String wanted,boolean quality){List<String> values=new ArrayList<>();values.add(c.optString("name"));JSONArray a=c.optJSONArray("alt_names");if(a!=null)for(int n=0;n<a.length();n++)values.add(a.optString(n));for(String value:values)if((quality?channel(value):normalized(value)).equals(wanted))return true;return false;}
 private static int english(JSONObject image){String language=image.optString("language",image.optString("languages"))+" "+image.optString("tags");language=language.toLowerCase(Locale.ROOT);return language.contains("english")||language.matches(".*\\ben\\b.*")?2:language.contains("arabic")||language.matches(".*\\bar\\b.*")?0:1;}
 static JSONObject match(String name,String id,JSONArray channels,JSONArray logos)throws Exception{List<JSONObject> found=new ArrayList<>();for(int n=0;n<channels.length();n++){JSONObject c=channels.optJSONObject(n);if(c==null)continue;if(!id.isEmpty()?id.equals(c.optString("id")):alias(c,normalized(name),false))found.add(c);}if(found.isEmpty()&&id.isEmpty())for(int n=0;n<channels.length();n++){JSONObject c=channels.optJSONObject(n);if(c!=null&&alias(c,channel(name),true))found.add(c);}if(found.isEmpty()&&id.isEmpty()&&normalized(name).matches("امبيسي[0-9]{1,2}")){String number=normalized(name).substring("امبيسي".length());for(int n=0;n<channels.length();n++){JSONObject c=channels.optJSONObject(n);if(c==null||!channel(c.optString("name")).equals("mbc"+number))continue;JSONArray owners=c.optJSONArray("owners");if(owners!=null)for(int k=0;k<owners.length();k++)if(normalized(owners.optString(k)).equals("mbcgroup")){found.add(c);break;}}}Set<String> ids=new HashSet<>();for(JSONObject c:found)ids.add(c.optString("id"));List<JSONObject> images=new ArrayList<>();for(int n=0;n<logos.length();n++){JSONObject l=logos.optJSONObject(n);if(l!=null&&ids.contains(l.optString("channel"))&&l.optBoolean("in_use")&&l.optString("url").startsWith("https://"))images.add(l);}boolean brand=false;if(found.size()>1){boolean same=true;String first=channel(found.get(0).optString("name"));Set<String> common=null;for(JSONObject c:found){if(!first.equals(channel(c.optString("name"))))same=false;Set<String> owners=new HashSet<>();JSONArray o=c.optJSONArray("owners");if(o!=null)for(int n=0;n<o.length();n++){String family=normalized(o.optString(n).replaceAll("(?i)\\b(?:corporation|corp|inc|limited|ltd|llc|emea|europe)\\b",""));if(family.length()>=4)owners.add(family);}if(common==null)common=owners;else common.retainAll(owners);}brand=same&&common!=null&&!common.isEmpty();}images.sort((a,b)->{int language=Integer.compare(english(b),english(a));return language!=0?language:Long.compare(b.optLong("width")*b.optLong("height"),a.optLong("width")*a.optLong("height"));});JSONArray candidates=new JSONArray();for(JSONObject c:found)candidates.put(new JSONObject().put("id",c.optString("id")).put("name",c.optString("name")));JSONObject preferred=found.isEmpty()?null:found.get(0);if(!images.isEmpty())for(JSONObject row:found)if(row.optString("id").equals(images.get(0).optString("channel")))preferred=row;String network="";if(!found.isEmpty()){network=found.get(0).isNull("network")?"":found.get(0).optString("network");for(JSONObject channel:found)if(!network.equals(channel.optString("network")))network="";}return new JSONObject().put("englishName",preferred==null?name:preferred.optString("name")).put("country",preferred==null?"US":preferred.optString("country")).put("network",network).put("status",found.isEmpty()?"not_found":images.isEmpty()?"no_image":"matched").put("channel",found.size()==1?found.get(0).optString("id"):!brand&&!images.isEmpty()?images.get(0).optString("channel"):"").put("automatic",found.size()>1).put("brandOnly",brand).put("images",new JSONArray(images)).put("candidates",candidates).put("source","https://github.com/iptv-org/api");}
}
